{id:69,title:"The Perfect System of the Indicative Passive",subtitle:"Passive voice and ablatives",concept:"Perfect passive is the fourth principal part plus sum: laudātus est. Participle agrees with subject.",referenceTable:{title:"Passive Reference",headers:["Form","Meaning"],rows:[["vehementer","violently, greatly","explōrō","investigate","premō","oppress","retineō","retain"]]},vocabularyTable:vt("Lesson 69 Vocabulary",[w("vehementer","violently, greatly","weh-HEH-men-tehr"),w("explōrō","investigate","eks-PLOH-roh"),w("premō","oppress","PREH-moh"),w("retineō","retain","reh-tee-NAY-oh"),w("comparō","prepare, compare","kom-PAH-roh")]),vocabulary:[w("vehementer","violently, greatly","weh-HEH-men-tehr"),w("explōrō","investigate","eks-PLOH-roh"),w("premō","oppress","PREH-moh"),w("retineō","retain","reh-tee-NAY-oh"),w("comparō","prepare, compare","kom-PAH-roh")],teachingSteps:[{title:"Core Pattern",explanation:"Perfect passive is the fourth principal part plus sum: laudātus est. Participle agrees with subject.",exampleLatin:"laudātur",exampleEnglish:"he is praised"},{title:"Guided Practice",explanation:"Use endings and case markers to identify the construction.",exampleLatin:"ā nautā laudātur",exampleEnglish:"he is praised by the sailor"}],comprehensionCheck:[{question:"What does -tur mark?",options:["third-person singular passive","first-person plural active","agent noun"],correctIndex:0,explanation:"-tur is the third-person singular passive ending."},{question:"How is a personal agent marked?",options:["ā/ab + ablative","bare ablative","cum + accusative"],correctIndex:0,explanation:"A personal agent uses ā or ab with the ablative."}],exercises:[mc("l69-q1","Which statement is correct?",["The passive subject receives the action","The passive subject always acts","Passive has no endings"],0),mc("l69-q2","Which form is passive?",["laudātur","laudat","laudō"],0),fill("l69-q3","Complete the passive ending: laudā___","tur",["tur","laudātur"]),mc("l69-q4","An agent is marked by…",["ā/ab + ablative","bare ablative always","cum only"],0),fill("l69-q5","Translate the key passive form.","is praised",["he is praised","praised"]),match("l69-q6","Match grammar and meaning",[mp("-tur","he/she/it is"),mp("-ntur","they are"),mp("cum + abl.","with")])]},
{id:70,title:"Mastery Review Vocab #2",subtitle:"Passive voice and ablatives",concept:"Review passive endings, agency, means, accompaniment, and perfect passive across Lessons 11–21.",referenceTable:{title:"Passive Reference",headers:["Form","Meaning"],rows:[["laudātur","is praised","mittuntur","are sent","audīmur","we are heard","ā Caesare","by Caesar"]]},vocabularyTable:vt("Lesson 70 Vocabulary",[w("laudātur","is praised","low-DAH-toor"),w("mittuntur","are sent","MIT-toon-toor"),w("audīmur","we are heard","OW-dee-moor"),w("ā Caesare","by Caesar","ah KAI-sah-reh"),w("gladiō","by a sword","GLAH-dee-oh"),w("cum amīcīs","with friends","koom ah-MEE-kees")]),vocabulary:[w("laudātur","is praised","low-DAH-toor"),w("mittuntur","are sent","MIT-toon-toor"),w("audīmur","we are heard","OW-dee-moor"),w("ā Caesare","by Caesar","ah KAI-sah-reh"),w("gladiō","by a sword","GLAH-dee-oh"),w("cum amīcīs","with friends","koom ah-MEE-kees")],teachingSteps:[{title:"Core Pattern",explanation:"Review passive endings, agency, means, accompaniment, and perfect passive across Lessons 11–21.",exampleLatin:"laudātur",exampleEnglish:"he is praised"},{title:"Guided Practice",explanation:"Use endings and case markers to identify the construction.",exampleLatin:"ā nautā laudātur",exampleEnglish:"he is praised by the sailor"}],comprehensionCheck:[{question:"What does -tur mark?",options:["third-person singular passive","first-person plural active","agent noun"],correctIndex:0,explanation:"-tur is the third-person singular passive ending."},{question:"How is a personal agent marked?",options:["ā/ab + ablative","bare ablative","cum + accusative"],correctIndex:0,explanation:"A personal agent uses ā or ab with the ablative."}],exercises:[mc("l70-q1","Which statement is correct?",["The passive subject receives the action","The passive subject always acts","Passive has no endings"],0),mc("l70-q2","Which form is passive?",["laudātur","laudat","laudō"],0),fill("l70-q3","Complete the passive ending: laudā___","tur",["tur","laudātur"]),mc("l70-q4","An agent is marked by…",["ā/ab + ablative","bare ablative always","cum only"],0),fill("l70-q5","Translate the key passive form.","is praised",["he is praised","praised"]),match("l70-q6","Match grammar and meaning",[mp("-tur","he/she/it is"),mp("-ntur","they are"),mp("cum + abl.","with")]),
{
  type: "reading-passage",
  id: "rp70",
  title: "Pāx ā Caesare",
  passage: "Oppidum Gallōrum ā Caesare oppugnātum est. Mīlitēs Rōmānī tēlīs et gladiīs pugnāvērunt. Gallī fortiter pugnāvērunt sed superātī sunt. Imperātor Gallōrum ā Caesare servātus est. Caesar pācem Gallīs dedit. Itaque omnēs grātiās Caesārī agēbant.",
  translation: "The town of the Gauls was attacked by Caesar. The Roman soldiers fought with weapons and swords. The Gauls fought bravely but were overcome. The general of the Gauls was saved by Caesar. Caesar gave peace to the Gauls. Therefore all were giving thanks to Caesar.",
  source: "Original composition — Eloqui Latin",
  glosses: [],
  passThreshold: 0.8,
  questions: [
    mc("r70-q1","What happened to the general of the Gauls?",["He was saved by Caesar","He was killed in the battle","He fled to Rome","He was handed over to the enemy"],0,"Imperātor Gallōrum ā Caesare servātus est — he was saved by Caesar."),
    mc("r70-q2","Which sentence means 'The Gauls were overcome'?",["Gallī superātī sunt.","Gallī superant.","Gallī superāvērunt.","Gallī superantur."],0,"superātī sunt = they were overcome (perfect passive)."),
    fill("r70-q3","The town of the Gauls was attacked by Caesar: Oppidum Gallōrum ā Caesare ___ est.","oppugnātum",["oppugnatum"],"oppugnātum est = was attacked (perfect passive of oppugnō)."),
    fill("r70-q4","Translate into Latin: The Gauls fought bravely but were overcome.","Gallī fortiter pugnāvērunt sed superātī sunt.",["Galli fortiter pugnaverunt sed superati sunt."],"pugnāvērunt = they fought; superātī sunt = they were overcome."),
    fill("r70-q5","Translate into Latin: Caesar gave peace to the Gauls.","Caesar pācem Gallīs dedit.",["Caesar pacem Gallis dedit."],"pācem = peace (accusative); Gallīs = to the Gauls (dative).")
  ]
},
{type:"culture-question",id:"cu70-q1",prompt:"The slave revolt led by the gladiator Spartacus against Rome took place in…",options:["73–71 BC","133–121 BC","27 BC – AD 14","AD 410–476"],correctIndex:0,explanation:"The slave revolt led by the gladiator Spartacus — the Third Servile War — ran from 73 to 71 BC and was finally crushed by Crassus. 133–121 BC is the Gracchan era, 27 BC–AD 14 is the reign of Augustus, and AD 410–476 is the western empire's fall: none of them the revolt.",source:"OCD s.v. Spartacus: leader of the Third Servile War (73–71 BC), defeated by Crassus.",domain:"history"},]},
// ── UNIT 6 · LESSON 22 · PRESENT SUBJUNCTIVE; PURPOSE CLAUSES ───
{id:71,title:"The Present Subjunctive Active",subtitle:"Formation across all four conjugations",concept:"The <strong>subjunctive</strong> is a <strong>mood</strong>, not a tense: it presents action as <strong>possible, wished for, or purposeful</strong>, while the <strong>indicative</strong> states facts. The <strong>present subjunctive active</strong> is formed differently in the four conjugations. In the <strong>first conjugation</strong> the stem vowel -ā- changes to <strong>-ē-</strong>: <em>amem, amēs, amet</em> ('I may love'). The <strong>second, third, and fourth</strong> conjugations add <strong>-ā-</strong> to the stem: <em>moneam</em>, <em>mittam</em>, <em>audiam</em>.",referenceTable:{title:"The Present Subjunctive Active",headers:["Conj.","1st sg.","2nd sg.","3rd sg.","1st pl.","3rd pl."],rows:[["1st (amō)","amem","amēs","amet","amēmus","ament"],["2nd (moneō)","moneam","moneās","moneat","moneāmus","moneant"],["3rd (mittō)","mittam","mittās","mittat","mittāmus","mittant"],["4th (audiō)","audiam","audiās","audiat","audiāmus","audiant"]],highlightRows:[0]},vocabularyTable:vt("Lesson 71 Vocabulary",[w("vīta","life","VEE-tah","f.","1st decl."),w("vallum","rampart, wall","VAHL-loom","n.","2nd decl."),w("amīcitia","friendship","ah-mee-KEE-tsee-ah","f.","1st decl."),w("fossa","ditch, trench","FOS-sah","f.","1st decl."),w("celeriter","quickly","cheh-LEH-ree-tehr")]),vocabulary:[w("vīta","life","VEE-tah","f.","1st decl."),w("vallum","rampart, wall","VAHL-loom","n.","2nd decl."),w("amīcitia","friendship","ah-mee-KEE-tsee-ah","f.","1st decl."),w("fossa","ditch, trench","FOS-sah","f.","1st decl."),w("celeriter","quickly","cheh-LEH-ree-tehr")],teachingSteps:[{title:"A New Mood",explanation:"Latin verbs have moods. The indicative states facts: amat means 'he loves.' The subjunctive presents action as possible, desired, or purposeful — not simply asserted. This is the first time you meet it.",exampleLatin:"amat / amet",exampleEnglish:"he loves (fact) / he may love (subjunctive)",tip:"Mood is about how the speaker presents the action, not when it happens."},{title:"First Conjugation: -ā- becomes -ē-",explanation:"In the first conjugation the present subjunctive changes the stem vowel -ā- to -ē-: amā- becomes amē-. The 1st-person singular ends in -m: amem, not amō.",exampleLatin:"amem, amēs, amet, amēmus, amētis, ament",exampleEnglish:"I may love, you may love, he/she may love, we may love, you (pl.) may love, they may love",tip:"amet (may love) differs from amat (loves) only in that -ē-."},{title:"Second, Third, and Fourth: add -ā-",explanation:"The other conjugations add -ā- to the present stem: mone-ā-m → moneam; mitt-ā-m → mittam; audi-ā-m → audiam. Their endings are -am, -ās, -at, -āmus, -ātis, -ant.",exampleLatin:"moneam, mittam, audiam",exampleEnglish:"I may warn, I may send, I may hear",tip:"mittam is also the future of mittō — let the context tell you which is meant."}],comprehensionCheck:[{question:"The subjunctive mood presents action as…",options:["possible, wished for, or purposeful","a plain fact","always past","always future"],correctIndex:0,explanation:"The indicative states facts; the subjunctive presents action from another angle — purpose, possibility, wish."},{question:"The present subjunctive of amō (1st sg.) is…",options:["amem","amō","amet","amāvī"],correctIndex:0,explanation:"First conjugation changes -ā- to -ē-: amem, 'I may love'."},{question:"Which form is the present subjunctive of moneō?",options:["moneam","moneō","monēbam","monuī"],correctIndex:0,explanation:"Second conjugation adds -ā- to the stem: moneam, 'I may warn'."}],exercises:[mc("l71-q1","vīta means…",["life","rampart","friendship","ditch"],0),mc("l71-q2","The present subjunctive of amō (1st sg.) is…",["amem","amō","amet","amāmus"],0),fill("l71-q3","amō: he may love = am___","et",["et","amet"]),mc("l71-q4","Which form is subjunctive, not indicative?",["amet","amat","amant","amāmus"],0),mc("l71-q5","The present subjunctive of mittō (1st sg.) is…",["mittam","mittō","mittēbam","mīsī"],0),fill("l71-q6","vallum means ___","rampart, wall",["rampart","wall","a rampart"]),mc("l71-q7","amīcitia means…",["friendship","life","ditch","quickly"],0),match("l71-q8","Match noun and meaning",[mp("vīta","life"),mp("vallum","rampart, wall"),mp("amīcitia","friendship"),mp("fossa","ditch, trench")]),mc("l71-q9","celeriter means…",["quickly","for a long time","sharply","easily"],0)]},
{id:72,title:"Mood in Purpose Clauses",subtitle:"ut + subjunctive expresses purpose",concept:"A <strong>purpose clause</strong> answers the question <strong>why?</strong> or <strong>for what purpose?</strong> It is introduced by <strong>ut</strong> ('in order that, so that') and its verb is in the <strong>subjunctive</strong>. <em>Venit ut videat</em> = 'he comes to see' — literally 'he comes so that he may see.' The subjunctive is the grammatical signal that the clause expresses purpose, not a statement of fact.",referenceTable:{title:"Purpose Clauses",headers:["Latin","English"],rows:[["Venit ut videat","He comes to see (so that he may see)"],["Mittit nūntium ut eum videat","He sends a messenger to see him"],["Venit ut pugnet","He comes to fight"]],highlightRows:[0]},vocabularyTable:vt("Lesson 72 Vocabulary",[w("ut","in order that, so that, that","oot"),w("veniō","I come","VEH-nee-oh"),w("videō","I see","VEE-deh-oh"),w("mittō","I send","MEET-toh"),w("celeriter","quickly","cheh-LEH-ree-tehr")]),vocabulary:[w("ut","in order that, so that, that","oot"),w("veniō","I come","VEH-nee-oh"),w("videō","I see","VEE-deh-oh"),w("mittō","I send","MEET-toh"),w("celeriter","quickly","cheh-LEH-ree-tehr")],teachingSteps:[{title:"Purpose Clauses Answer Why",explanation:"A purpose clause explains the goal of the main action — it answers 'why?' or 'for what purpose?' English often uses 'to + verb'; Latin uses ut ('in order that') with the subjunctive.",exampleLatin:"Venit ut videat.",exampleEnglish:"He comes to see (in order that he may see).",tip:"If you can translate a clause with 'to …', it is probably a purpose clause."},{title:"ut + Subjunctive",explanation:"After ut in a purpose clause the verb must be subjunctive: videat, not videt. The subjunctive signals purpose; the indicative would turn the clause into a statement of fact.",exampleLatin:"Mittit nūntium ut eum videat.",exampleEnglish:"He sends a messenger to see him.",tip:"videt (indicative) = he sees; videat (subjunctive) = he may see / to see."},{title:"Recognizing the Pattern",explanation:"Find ut, then check the verb: if it is subjunctive, you have a purpose clause. Translate ut + subjunctive as 'to …' or 'in order that … may …'.",exampleLatin:"Venit ut pugnet.",exampleEnglish:"He comes to fight (in order that he may fight).",tip:"pugnet = may fight — the present subjunctive of pugnō."}],comprehensionCheck:[{question:"A purpose clause expresses…",options:["the goal or intention of the main action","a plain fact","a past event","possession"],correctIndex:0,explanation:"Purpose clauses answer 'why?' or 'for what purpose?'."},{question:"The verb in a purpose clause is in the…",options:["subjunctive","indicative","imperative","future only"],correctIndex:0,explanation:"ut + subjunctive marks purpose."},{question:"Venit ut videat means…",options:["he comes to see","he comes because he sees","he sees that he comes","he came to see"],correctIndex:0,explanation:"ut videat = so that he may see, i.e., to see."}],exercises:[mc("l72-q1","ut in a purpose clause means…",["in order that, so that","because","but","after"],0),mc("l72-q2","The verb of a purpose clause is in the…",["subjunctive","indicative","imperative","future only"],0),mc("l72-q3","Venit ut videat means…",["he comes to see","he comes because he sees","he sees the coming","he came to see"],0),fill("l72-q4","Complete: Venit ___ videat. (so that he may see)","ut"),mc("l72-q5","Which is the subjunctive form?",["videat","videt","vidēbat","vidēbit"],0),fill("l72-q6","Translate: Venit ut pugnet","he comes to fight",["he comes so that he may fight","he comes in order to fight"]),mc("l72-q7","veniō means…",["I come","I see","I send","I wait"],0),match("l72-q8","Match verb and meaning",[mp("veniō","I come"),mp("videō","I see"),mp("mittō","I send"),mp("pugnō","I fight")])]},
{id:73,title:"Primary Tenses: Sequence of Tenses",subtitle:"Present/future main verb → present subjunctive",concept:"The <strong>sequence of tenses</strong> links the subjunctive of a purpose clause to the tense of the <strong>main verb</strong>. When the main verb is <strong>present or future</strong> — the <strong>primary</strong> tenses — the purpose clause uses the <strong>present subjunctive</strong>. <em>Venit ut videat</em> ('he comes to see'); <em>Veniet ut videat</em> ('he will come to see'). A past main verb, by contrast, takes the imperfect subjunctive (Lesson 76).",referenceTable:{title:"Sequence of Tenses in Purpose Clauses",headers:["Main verb","Type","Purpose clause verb","Example"],rows:[["present","primary","present subjunctive","Venit ut videat — he comes to see"],["future","primary","present subjunctive","Veniet ut videat — he will come to see"],["imperfect","secondary","imperfect subjunctive","Venībat ut vidēret — he was coming to see"],["perfect","secondary","imperfect subjunctive","Vēnit ut vidēret — he came to see"]],highlightRows:[0,1]},vocabularyTable:vt("Lesson 73 Vocabulary",[w("exspectō, exspectāre","wait for, expect","eks-PEK-toh"),w("novus, -a, -um","new","NOH-voos / NOH-vah / NOH-voom"),w("diū","for a long time","DEE-oo"),w("ācriter","sharply, fiercely","AH-kree-tehr"),w("expugnō, expugnāre","storm, take by storm","eks-POON-yoh")]),vocabulary:[w("exspectō, exspectāre","wait for, expect","eks-PEK-toh"),w("novus, -a, -um","new","NOH-voos / NOH-vah / NOH-voom"),w("diū","for a long time","DEE-oo"),w("ācriter","sharply, fiercely","AH-kree-tehr"),w("expugnō, expugnāre","storm, take by storm","eks-POON-yoh")],teachingSteps:[{title:"Primary and Secondary",explanation:"The sequence of tenses links the subjunctive of a purpose clause to the tense of the main verb. Present and future main verbs are primary; past tenses (imperfect, perfect, pluperfect) are secondary.",exampleLatin:"Venit ut videat.",exampleEnglish:"He comes to see.",tip:"Primary sequence keeps the idea 'present-to-present'."},{title:"Primary Main Verb → Present Subjunctive",explanation:"If the main verb is present or future, the purpose clause uses the present subjunctive: exspectat ut videat (he waits to see); veniet ut pugnet (he will come to fight).",exampleLatin:"Exspectat ut videat.",exampleEnglish:"He is waiting to see (so that he may see).",tip:"With a present main verb, keep videat — the present subjunctive."},{title:"Reading the Whole Sentence",explanation:"Decide the sequence from the MAIN verb, not from the purpose clause. Veniet (future) is primary, so the purpose clause stays in the present subjunctive.",exampleLatin:"Veniet ut oppidum expugnet.",exampleEnglish:"He will come to storm the town.",tip:"expugnet = present subjunctive of expugnō, 'to take by storm'."}],comprehensionCheck:[{question:"Which main-verb tenses are primary?",options:["present and future","imperfect and perfect","pluperfect only","all past tenses"],correctIndex:0,explanation:"Primary tenses are present and future; they take the present subjunctive in purpose clauses."},{question:"In Venit ut videat, videat is the…",options:["present subjunctive","imperfect subjunctive","present indicative","infinitive"],correctIndex:0,explanation:"A present main verb (primary sequence) takes the present subjunctive."},{question:"novus means…",options:["new","old","wide","long"],correctIndex:0,explanation:"novus, -a, -um is the adjective meaning 'new'."}],exercises:[mc("l73-q1","exspectō means…",["I wait for, expect","I storm","I see","I come"],0),mc("l73-q2","Which tenses are primary?",["present and future","imperfect and perfect","pluperfect only","all past tenses"],0),fill("l73-q3","In Venit ut videat, videat is the ___ subjunctive","present",["present tense","pres."]),mc("l73-q4","Veniet ut videat — the purpose clause stays in the…",["present subjunctive","imperfect subjunctive","future indicative","perfect"],0),mc("l73-q5","ācriter means…",["sharply, fiercely","for a long time","quickly","easily"],0),fill("l73-q6","expugnō means: I ___","storm",["take by storm","storm, take by storm"]),mc("l73-q7","diū means…",["for a long time","quickly","sharply","new"],0),match("l73-q8","Match word and meaning",[mp("exspectō","I wait for"),mp("expugnō","I storm"),mp("novus","new"),mp("ācriter","sharply, fiercely")]),fill("l73-q9","Translate: Veniet ut expugnet","he will come to storm",["he will come so that he may storm"])]},
{id:74,title:"Negative Purpose Clauses",subtitle:"nē + subjunctive: so that...not",concept:"To express a <strong>negative purpose</strong> — 'so that something will <strong>not</strong> happen' — Latin uses <strong>nē</strong> instead of ut, still with the subjunctive. <em>Fugit nē videātur</em> = 'he flees so that he may not be seen.' The pairing to remember: <strong>ut</strong> + subjunctive = 'so that'; <strong>nē</strong> + subjunctive = 'so that...not, lest.'",referenceTable:{title:"Positive vs. Negative Purpose",headers:["Type","Introduction","Example"],rows:[["positive purpose","ut + subjunctive","Pugnat ut vincat — he fights to conquer"],["negative purpose","nē + subjunctive","Fugit nē videātur — he flees so that he may not be seen"]],highlightRows:[1]},vocabularyTable:vt("Lesson 74 Vocabulary",[w("nē","so that...not, lest","nay"),w("fugiō, fugere","I flee","FOO-jee-oh"),w("taceō, tacēre","I am silent","TAH-cheh-oh"),w("hostis","enemy","HOS-tees","m.","3rd decl."),w("celeriter","quickly","cheh-LEH-ree-tehr")]),vocabulary:[w("nē","so that...not, lest","nay"),w("fugiō, fugere","I flee","FOO-jee-oh"),w("taceō, tacēre","I am silent","TAH-cheh-oh"),w("hostis","enemy","HOS-tees","m.","3rd decl."),w("celeriter","quickly","cheh-LEH-ree-tehr")],teachingSteps:[{title:"Saying Not",explanation:"The negative purpose clause is introduced by nē ('so that...not, lest') instead of ut. The verb stays subjunctive.",exampleLatin:"Fugit nē videātur.",exampleEnglish:"He flees so that he may not be seen.",tip:"nē = 'so that...not' — the negative twin of ut. videātur is a passive subjunctive form; you will study passives of the subjunctive fully later."},{title:"nē vs. ut",explanation:"Use ut for a positive goal, nē for a negative one: pugnat ut vincat (he fights to conquer); tacent nē hostēs eōs audiant (they are silent so that the enemies may not hear them).",exampleLatin:"Tacent nē hostēs eōs audiant.",exampleEnglish:"They are silent so that the enemies may not hear them.",tip:"audiant = present subjunctive of audiō, 'I hear'; eōs = them (acc. pl. of is, ea, id)."},{title:"Spotting nē + Subjunctive",explanation:"Whenever you see nē followed by a subjunctive verb, translate 'so that...not' or 'lest'. The subjunctive mood is what marks the clause as purpose.",exampleLatin:"Celeriter fugiunt nē hostēs eōs videant.",exampleEnglish:"They flee quickly so that the enemies may not see them.",tip:"videant = present subjunctive of videō."}],comprehensionCheck:[{question:"Negative purpose is introduced by…",options:["nē","ut","quod","et"],correctIndex:0,explanation:"nē ('so that...not, lest') introduces negative purpose clauses."},{question:"Fugit nē videātur means…",options:["he flees so that he may not be seen","he flees in order to be seen","he does not flee","they flee so as not to be seen"],correctIndex:0,explanation:"nē videātur = so that he may not be seen."},{question:"Which word completes a negative purpose clause: Pugnant ___ hostēs vincant.",options:["nē","ut","quod","sed"],correctIndex:0,explanation:"A negative purpose clause uses nē with the subjunctive: so that the enemies may not conquer."}],exercises:[mc("l74-q1","nē means…",["so that...not, lest","so that","because","and not"],0),mc("l74-q2","A negative purpose clause uses ___ + subjunctive.",["nē","ut","quod","cum"],0),mc("l74-q3","Fugit nē videātur means…",["he flees so that he may not be seen","he flees to be seen","he does not flee","they flee so as not to be seen"],0),fill("l74-q4","fugiō means: I ___","flee",["am fleeing"]),mc("l74-q5","Which clause is negative purpose?",["Fugit nē hostēs eum videant","Fugit ut hostēs eum videant","Venit ut videat","Exspectat ut pugnet"],0),fill("l74-q6","Complete: Tacent ___ hostēs eōs audiant.","nē"),mc("l74-q7","taceō means…",["I am silent","I flee","I hear","I fight"],0),match("l74-q8","Match word and meaning",[mp("ut","so that"),mp("nē","so that...not"),mp("fugiō","I flee"),mp("taceō","I am silent")]),fill("l74-q9","Translate: Celeriter fugiunt nē hostēs eōs videant","they flee quickly so that the enemies may not see them",["they quickly flee lest the enemies see them"])]},
// ── UNIT 6 · LESSON 23 · IMPERFECT SUBJUNCTIVE ACTIVE ───────────
{id:75,title:"The Imperfect Subjunctive Active",subtitle:"Infinitive + personal endings: amārem",concept:"The <strong>imperfect subjunctive active</strong> is the simplest subjunctive to form: take the <strong>present active infinitive</strong> (the second principal part) and add the personal endings <strong>-m, -s, -t, -mus, -tis, -nt</strong>. <em>amāre</em> + -m = <em>amārem</em> ('I might love'); <em>monēre</em> + -m = <em>monērem</em>; <em>mittere</em> + -m = <em>mitterem</em>; <em>audīre</em> + -m = <em>audīrem</em>. One rule works for <strong>every conjugation</strong>.",referenceTable:{title:"The Imperfect Subjunctive Active",headers:["Conj.","Infinitive","1st sg.","2nd sg.","3rd sg.","3rd pl."],rows:[["1st","amāre","amārem","amārēs","amāret","amārent"],["2nd","monēre","monērem","monērēs","monēret","monērent"],["3rd","mittere","mitterem","mitterēs","mitteret","mitterent"],["4th","audīre","audīrem","audīrēs","audīret","audīrent"]],highlightRows:[0]},vocabularyTable:vt("Lesson 75 Vocabulary",[w("tribūnus","tribune","tree-BOO-noos","m.","2nd decl."),w("cōnsilium","plan, counsel","kon-SEE-lee-oom","n.","2nd decl."),w("concilium","assembly, council","kon-KEE-lee-oom","n.","2nd decl."),w("lēgātus","envoy, lieutenant","lay-GAH-toos","m.","2nd decl."),w("lātus, -a, -um","wide","LAH-toos / LAH-tah / LAH-toom"),w("facile","easily","FAH-chee-leh")]),vocabulary:[w("tribūnus","tribune","tree-BOO-noos","m.","2nd decl."),w("cōnsilium","plan, counsel","kon-SEE-lee-oom","n.","2nd decl."),w("concilium","assembly, council","kon-KEE-lee-oom","n.","2nd decl."),w("lēgātus","envoy, lieutenant","lay-GAH-toos","m.","2nd decl."),w("lātus, -a, -um","wide","LAH-toos / LAH-tah / LAH-toom"),w("facile","easily","FAH-chee-leh")],teachingSteps:[{title:"The One-Rule Formation",explanation:"Take the present active infinitive (the second principal part) and add the personal endings -m, -s, -t, -mus, -tis, -nt. Because every infinitive ends in -re, every imperfect subjunctive shows -re- before the ending.",exampleLatin:"amāre → amārem",exampleEnglish:"to love → I might love",tip:"One rule for all four conjugations — nothing else to memorize."},{title:"The Four Model Verbs",explanation:"amārem (1st), monērem (2nd), mitterem (3rd), audīrem (4th). The endings are identical in every conjugation; only the infinitive differs.",exampleLatin:"monērem, mitterem, audīrem",exampleEnglish:"I might warn, I might send, I might hear",tip:"The stem is simply the full infinitive."},{title:"Reading the Forms",explanation:"The -re- before the ending is the fingerprint of the imperfect subjunctive: amāret (might love) vs. amet (may love).",exampleLatin:"amāret / amet",exampleEnglish:"he might love / he may love",tip:"Long -āre- marks the imperfect; short -e- the present subjunctive."}],comprehensionCheck:[{question:"The imperfect subjunctive is formed from…",options:["the present active infinitive + personal endings","the perfect stem","the future stem","the 4th principal part"],correctIndex:0,explanation:"Add -m, -s, -t, -mus, -tis, -nt to the present active infinitive."},{question:"The imperfect subjunctive of amō (1st sg.) is…",options:["amārem","amem","amābam","amāvī"],correctIndex:0,explanation:"amāre + -m = amārem, 'I might love'."},{question:"Which form is the imperfect subjunctive of mittō?",options:["mitterem","mittam","mittēbam","mīsī"],correctIndex:0,explanation:"mittere + -m = mitterem, 'I might send'."}],exercises:[mc("l75-q1","tribūnus means…",["tribune","plan","assembly","envoy"],0),fill("l75-q2","amō: I might love = amā___","rem",["rem","amārem"]),mc("l75-q3","The imperfect subjunctive is formed from the ___ + personal endings.",["present active infinitive","perfect stem","future stem","present stem only"],0),mc("l75-q4","The imperfect subjunctive of audiō (1st sg.) is…",["audīrem","audiam","audiēbam","audīvī"],0),fill("l75-q5","cōnsilium means ___","plan, counsel",["plan","counsel","a plan"]),mc("l75-q6","lēgātus means…",["envoy, lieutenant","tribune","hostage","guard"],0),mc("l75-q7","concilium means…",["assembly, council","plan","friendship","memory"],0),match("l75-q8","Match word and meaning",[mp("tribūnus","tribune"),mp("cōnsilium","plan, counsel"),mp("lēgātus","envoy"),mp("lātus","wide")]),fill("l75-q9","facile means ___","easily")]},
{id:76,title:"Secondary Tenses: Sequence of Tenses",subtitle:"Past main verb → imperfect subjunctive",concept:"When the main verb is in a <strong>past tense</strong> — imperfect, perfect, or pluperfect — the sentence is in <strong>secondary sequence</strong>, and the purpose clause uses the <strong>imperfect subjunctive</strong>. <em>Vēnit ut vidēret</em> = 'he came to see' (literally 'he came so that he might see'). Contrast with primary sequence: <em>Venit ut videat</em> ('he comes to see').",referenceTable:{title:"Secondary Sequence in Purpose Clauses",headers:["Main verb","Type","Purpose clause verb","Example"],rows:[["imperfect","secondary","imperfect subjunctive","Venībat ut vidēret — he was coming to see"],["perfect","secondary","imperfect subjunctive","Vēnit ut vidēret — he came to see"],["pluperfect","secondary","imperfect subjunctive","Vēnerat ut vidēret — he had come to see"],["present","primary","present subjunctive","Venit ut videat — he comes to see"]],highlightRows:[0,1,2]},vocabularyTable:vt("Lesson 76 Vocabulary",[w("ut","in order that, so that, that","oot"),w("vēnit","he/she came","VAY-neet"),w("vēnērunt","they came","vay-NAY-roont"),w("lēgātus","envoy, lieutenant","lay-GAH-toos","m.","2nd decl."),w("cōnsilium","plan, counsel","kon-SEE-lee-oom","n.","2nd decl.")]),vocabulary:[w("ut","in order that, so that, that","oot"),w("vēnit","he/she came","VAY-neet"),w("vēnērunt","they came","vay-NAY-roont"),w("lēgātus","envoy, lieutenant","lay-GAH-toos","m.","2nd decl."),w("cōnsilium","plan, counsel","kon-SEE-lee-oom","n.","2nd decl.")],teachingSteps:[{title:"Past Main Verb → Imperfect Subjunctive",explanation:"If the main verb is a past tense (imperfect, perfect, pluperfect), the purpose clause shifts to the imperfect subjunctive. The action of the purpose clause is still future relative to the main verb, but the form must follow the sequence.",exampleLatin:"Vēnit ut vidēret.",exampleEnglish:"He came to see (so that he might see).",tip:"vidēret = might see — the imperfect subjunctive of videō."},{title:"The Two Sequences Compared",explanation:"Compare: Venit ut videat (he comes to see — present main verb) with Vēnit ut vidēret (he came to see — perfect main verb). Only the main verb changed, and the subjunctive shifted tense with it.",exampleLatin:"Venit ut videat / Vēnit ut vidēret",exampleEnglish:"he comes to see / he came to see",tip:"venit (present, short e) and vēnit (perfect, long ē) look alike — the main-verb tense you choose decides videat or vidēret."},{title:"Practice the Pairing",explanation:"Lēgātus vēnit ut cōnsilium peteret — the envoy came to seek a plan (petō, 'I seek'). The perfect vēnit forces the imperfect subjunctive peteret.",exampleLatin:"Lēgātus vēnit ut cōnsilium peteret.",exampleEnglish:"The envoy came to seek a plan.",tip:"peteret = might seek — the imperfect subjunctive of petō."}],comprehensionCheck:[{question:"Secondary sequence is triggered by a ___ main verb.",options:["past","present","future","imperative"],correctIndex:0,explanation:"Past main verbs (imperfect, perfect, pluperfect) trigger the imperfect subjunctive."},{question:"Vēnit ut vidēret means…",options:["he came to see","he comes to see","he will come to see","they came to see"],correctIndex:0,explanation:"The perfect main verb vēnit takes the imperfect subjunctive vidēret: he came to see."},{question:"With a past main verb, the purpose clause uses the…",options:["imperfect subjunctive","present subjunctive","future indicative","perfect indicative"],correctIndex:0,explanation:"Past main verb → imperfect subjunctive in the purpose clause."}],exercises:[mc("l76-q1","vēnit means…",["he came","he comes","they came","he will come"],0),fill("l76-q2","Vēnit ut ___ (vidēre — imperfect subjunctive)","vidēret",["videret"]),mc("l76-q3","Vēnit ut vidēret means…",["he came to see","he comes to see","he will come to see","they came to see"],0),mc("l76-q4","Which main verb triggers secondary sequence?",["vēnit (he came)","venit (he comes)","veniet (he will come)","exspectat (he waits)"],0),fill("l76-q5","vēnērunt means: they ___","came",["have come"]),mc("l76-q6","With a past main verb, a purpose clause uses the…",["imperfect subjunctive","present subjunctive","future indicative","infinitive"],0),mc("l76-q7","In Lēgātus vēnit ut cōnsilium peteret, peteret is…",["imperfect subjunctive","present subjunctive","perfect indicative","infinitive"],0),match("l76-q8","Match sequence and subjunctive tense",[mp("present main verb","present subjunctive"),mp("perfect main verb","imperfect subjunctive"),mp("future main verb","present subjunctive"),mp("imperfect main verb","imperfect subjunctive")])]},
{id:77,title:"Adjectives Used as Nouns; Imperfect Subjunctive of sum",subtitle:"bonī = the good; essem, essēs, esset",concept:"An adjective can be used as a <strong>noun</strong>. The <strong>masculine plural</strong> names a group of people — <em>bonī</em> = 'the good (men)'; the <strong>neuter singular</strong> names the abstract idea — <em>bonum</em> = 'the good.' The verb <strong>sum</strong> forms its imperfect subjunctive by the same rule as every verb: infinitive <em>esse</em> + personal endings = <em>essem, essēs, esset, essēmus, essētis, essent</em> ('I might be', etc.).",referenceTable:{title:"The Imperfect Subjunctive of sum",headers:["Person","Singular","Plural"],rows:[["1st","essem","essēmus"],["2nd","essēs","essētis"],["3rd","esset","essent"]],highlightRows:[0]},vocabularyTable:vt("Lesson 77 Vocabulary",[w("labor, labōris","labor, toil","LAH-bor, lah-BOH-rees","m.","3rd decl."),w("ōrdō, ōrdinis","order, rank","OR-doh, or-DEE-nees","m.","3rd decl."),w("obses, obsidis","hostage","OB-ses, ob-SEE-dees","m./f.","3rd decl."),w("inter","between, among (+ acc.)","EEN-tehr"),w("statim","immediately","STAH-teem")]),vocabulary:[w("labor, labōris","labor, toil","LAH-bor, lah-BOH-rees","m.","3rd decl."),w("ōrdō, ōrdinis","order, rank","OR-doh, or-DEE-nees","m.","3rd decl."),w("obses, obsidis","hostage","OB-ses, ob-SEE-dees","m./f.","3rd decl."),w("inter","between, among (+ acc.)","EEN-tehr"),w("statim","immediately","STAH-teem")],teachingSteps:[{title:"Adjectives Can Be Nouns",explanation:"An adjective with no noun to modify can stand alone. The masculine plural names the people: bonī = the good (men), fortēs = the brave. The neuter singular names the abstract idea: bonum = the good (goodness).",exampleLatin:"Bonī virtūtem laudant.",exampleEnglish:"The good praise courage.",tip:"Supply the missing noun in your head: bonī = good (men)."},{title:"essem — Imperfect Subjunctive of sum",explanation:"sum follows the same rule as every verb: take the infinitive esse and add -m, -s, -t, -mus, -tis, -nt: essem, essēs, esset, essēmus, essētis, essent.",exampleLatin:"essem, essēs, esset",exampleEnglish:"I might be, you might be, he/she might be",tip:"esse + -m = essem — the pattern is identical to amāre + -m = amārem."},{title:"Putting Them Together",explanation:"In secondary sequence a purpose clause can use esset: vēnit ut esset cum amīcīs (he came to be with friends). Adjectives as nouns join the pattern too: obsidēs inter bonōs erant (the hostages were among the good).",exampleLatin:"Vēnit ut esset cum amīcīs.",exampleEnglish:"He came to be with friends.",tip:"esset = he might be — imperfect subjunctive of sum."}],comprehensionCheck:[{question:"bonī (masculine plural, used as a noun) means…",options:["the good (people)","goodness","the good thing","a good man"],correctIndex:0,explanation:"The masculine plural of an adjective used as a noun names a group of people: the good."},{question:"The imperfect subjunctive of sum (1st sg.) is…",options:["essem","eram","sum","fuī"],correctIndex:0,explanation:"esse + -m = essem, 'I might be'."},{question:"statim means…",options:["immediately","for a long time","easily","quickly"],correctIndex:0,explanation:"statim is an adverb meaning 'immediately'."}],exercises:[mc("l77-q1","bonī used as a noun means…",["the good (people)","goodness","the good thing","a good man"],0),fill("l77-q2","sum: I might be = ___","essem",["essem"]),mc("l77-q3","The imperfect subjunctive of sum is formed from ___ + personal endings.",["esse","eram","sum","fuī"],0),mc("l77-q4","essent means…",["they might be","we might be","they were","you might be"],0),fill("l77-q5","labor means ___","labor, toil",["toil","work"]),mc("l77-q6","inter takes the…",["accusative","ablative","genitive","dative"],0),mc("l77-q7","obses means…",["hostage","guard","envoy","tribune"],0),match("l77-q8","Match word and meaning",[mp("labor","labor, toil"),mp("ōrdō","order, rank"),mp("obses","hostage"),mp("statim","immediately")])]},
// ── UNIT 6 · LESSON 24 · RELATIVE CLAUSES; THE USE OF AD ────────
{id:78,title:"quī, quae, quod: The Relative Pronoun",subtitle:"The full paradigm",concept:"The <strong>relative pronoun</strong> <strong>quī, quae, quod</strong> means <strong>who, which, that</strong> and introduces a <strong>relative clause</strong> describing a noun, its <strong>antecedent</strong>. It agrees with the antecedent in <strong>gender and number</strong>, but its <strong>case</strong> comes from its own clause. <em>Mīles quī pugnat</em> = 'the soldier who fights.'",referenceTable:{title:"The Declension of quī, quae, quod",headers:["Case","Masc.","Fem.","Neut."],rows:[["Nominative","quī","quae","quod"],["Genitive","cuius","cuius","cuius"],["Dative","cui","cui","cui"],["Accusative","quem","quam","quod"],["Ablative","quō","quā","quō"],["Nom. plural","quī","quae","quae"],["Gen. plural","quōrum","quārum","quōrum"],["Dat./Abl. plural","quibus","quibus","quibus"],["Acc. plural","quōs","quās","quae"]],highlightRows:[0]},vocabularyTable:vt("Lesson 78 Vocabulary",[w("quī, quae, quod","who, which, that","kwee, KWEH, kwod"),w("auxilium","aid, help","owk-SEE-lee-oom","n.","2nd decl."),w("auxilia","auxiliary troops","owk-SEE-lee-ah","n. pl.","2nd decl."),w("memoria","memory","meh-MOR-ee-ah","f.","1st decl."),w("memoria teneō","to remember (hold in memory)","meh-MOR-ee-ah TEH-neh-oh")]),vocabulary:[w("quī, quae, quod","who, which, that","kwee, KWEH, kwod"),w("auxilium","aid, help","owk-SEE-lee-oom","n.","2nd decl."),w("auxilia","auxiliary troops","owk-SEE-lee-ah","n. pl.","2nd decl."),w("memoria","memory","meh-MOR-ee-ah","f.","1st decl."),w("memoria teneō","to remember (hold in memory)","meh-MOR-ee-ah TEH-neh-oh")],teachingSteps:[{title:"The Relative Clause",explanation:"A relative clause modifies a noun, the antecedent. quī, quae, quod = who, which, that. Mīles quī pugnat = the soldier who fights.",exampleLatin:"Mīles quī pugnat est fortis.",exampleEnglish:"The soldier who fights is brave.",tip:"The relative clause tells which soldier: quī pugnat, 'who fights'."},{title:"The Full Paradigm",explanation:"Learn the forms of quī, quae, quod: quī/quae/quod (nominative), cuius (genitive), cui (dative), quem/quam/quod (accusative), quō/quā/quō (ablative); plurals quī/quae/quae, quōrum, quibus, quōs/quās/quae.",exampleLatin:"quem / quam / quod",exampleEnglish:"whom (m.) / whom (f.) / which (n.) — accusative",tip:"cuius and cui are the same for all genders — an easy break."},{title:"Gender, Number, Case",explanation:"The relative agrees with its antecedent in gender and number, but takes its case from its own clause. Mīlitēs quōs vīdī = the soldiers whom I saw: quōs is masculine plural (matching mīlitēs) and accusative (object of vīdī).",exampleLatin:"Mīlitēs quōs vīdī sunt fortēs.",exampleEnglish:"The soldiers whom I saw are brave.",tip:"Ask: what noun does it stand for (gender/number)? what job does it do in its own clause (case)?"}],comprehensionCheck:[{question:"The relative pronoun quī, quae, quod means…",options:["who, which, that","because","so that","who? (question)"],correctIndex:0,explanation:"quī, quae, quod is the relative pronoun: who, which, that."},{question:"The relative pronoun agrees with its antecedent in…",options:["gender and number","case only","tense","person"],correctIndex:0,explanation:"Gender and number come from the antecedent; case comes from the relative's own clause."},{question:"auxilium means…",options:["aid, help","memory","envoy","hostage"],correctIndex:0,explanation:"auxilium, -ī is the neuter noun meaning aid, help."}],exercises:[mc("l78-q1","quī, quae, quod means…",["who, which, that","because","so that","who?"],0),mc("l78-q2","The accusative masculine singular of the relative pronoun is…",["quem","quī","cuius","quō"],0),fill("l78-q3","Genitive singular of the relative pronoun (all genders): ___","cuius",["cujus"]),mc("l78-q4","auxilium means…",["aid, help","memory","plan","life"],0),fill("l78-q5","memoria teneō means: to ___","remember",["hold in memory"]),mc("l78-q6","The relative pronoun agrees with its antecedent in gender and…",["number","case","person","mood"],0),mc("l78-q7","auxilia (plural) means…",["auxiliary troops","aids","helpers","memories"],0),match("l78-q8","Match form and case",[mp("quī","nominative masculine"),mp("quem","accusative masculine"),mp("cuius","genitive"),mp("quō","ablative")])]},
{id:79,title:"The Use of ad",subtitle:"ad + accusative: motion toward and purpose",concept:"The preposition <strong>ad</strong> takes the <strong>accusative</strong>. With verbs of motion it means <strong>to, toward</strong>: <em>vēnit ad oppidum</em> = 'he came to the town.' With nouns it can express <strong>purpose</strong>: <em>parātus ad bellum</em> = 'ready for war.' The adverb <strong>usque</strong> ('all the way') strengthens it: <em>usque ad flūmen</em> = 'all the way to the river.'",referenceTable:{title:"ad + Accusative",headers:["Phrase","Meaning","Use"],rows:[["ad oppidum","to the town","motion toward"],["ad flūmen","to the river","motion toward"],["parātus ad bellum","ready for war","purpose"],["usque ad Rōmam","all the way to Rome","strengthened motion"]],highlightRows:[0]},vocabularyTable:vt("Lesson 79 Vocabulary",[w("ad","to, toward, for the purpose of (+ acc.)","ahd"),w("usque","all the way, continuously","OOS-kweh"),w("perveniō, pervenīre","arrive, reach","pehr-VEH-nee-oh"),w("pertineō, pertinēre","pertain to, extend to","pehr-TEE-neh-oh"),w("parātus, -a, -um","prepared, ready","pah-RAH-toos / pah-RAH-tah / pah-RAH-toom"),w("ūtilis, -e","useful","OO-tee-lees / OO-tee-leh"),w("nox, noctis","night","noks, NOK-tees","f.","3rd decl.")]),vocabulary:[w("ad","to, toward, for the purpose of (+ acc.)","ahd"),w("usque","all the way, continuously","OOS-kweh"),w("perveniō, pervenīre","arrive, reach","pehr-VEH-nee-oh"),w("pertineō, pertinēre","pertain to, extend to","pehr-TEE-neh-oh"),w("parātus, -a, -um","prepared, ready","pah-RAH-toos / pah-RAH-tah / pah-RAH-toom"),w("ūtilis, -e","useful","OO-tee-lees / OO-tee-leh"),w("nox, noctis","night","noks, NOK-tees","f.","3rd decl.")],teachingSteps:[{title:"ad + Accusative for Motion",explanation:"ad with the accusative means to or toward after verbs of motion: venit ad oppidum (he comes to the town), mittit nūntium ad Caesarem (he sends a messenger to Caesar).",exampleLatin:"Vēnit ad oppidum.",exampleEnglish:"He came to the town.",tip:"ad + acc is motion toward — compare with in + acc, 'into'."},{title:"ad for Purpose",explanation:"ad with a noun can express purpose or readiness: parātus ad bellum (ready for war), ūtilis ad pugnam (useful for battle).",exampleLatin:"Mīlitēs parātī ad bellum sunt.",exampleEnglish:"The soldiers are ready for war.",tip:"Translate ad here as 'for' — the purpose meaning."},{title:"usque ad — All the Way",explanation:"The adverb usque (all the way) combines with ad: usque ad flūmen (all the way to the river). perveniō + ad means to arrive at: pervenīmus ad oppidum (we arrive at the town).",exampleLatin:"Usque ad Rōmam pervēnērunt.",exampleEnglish:"They arrived all the way to Rome.",tip:"usque emphasizes the full distance."}],comprehensionCheck:[{question:"ad takes the…",options:["accusative","ablative","genitive","dative"],correctIndex:0,explanation:"ad governs the accusative case."},{question:"ad oppidum means…",options:["to the town","in the town","from the town","through the town"],correctIndex:0,explanation:"ad + accusative = to, toward: to the town."},{question:"nox, noctis means…",options:["night","day","life","memory"],correctIndex:0,explanation:"nox is the third-declension noun for night."}],exercises:[mc("l79-q1","ad takes the…",["accusative","ablative","genitive","dative"],0),mc("l79-q2","parātus means…",["prepared, ready","useful","new","wide"],0),fill("l79-q3","'To the town': ad oppid___","um",["um","oppidum"]),mc("l79-q4","usque ad flūmen means…",["all the way to the river","in the river","from the river","to the bridge"],0),mc("l79-q5","perveniō means…",["I arrive, reach","I pertain","I flee","I come"],0),fill("l79-q6","ūtilis means ___","useful",["useful, useful"]),mc("l79-q7","nox means…",["night","day","dawn","noon"],0),match("l79-q8","Match word and meaning",[mp("ad","to, toward"),mp("usque","all the way"),mp("perveniō","I arrive"),mp("pertineō","I pertain to")])]},
{id:80,title:"Relative Clauses of Purpose",subtitle:"quī + subjunctive: 'who would...'",concept:"A <strong>relative clause of purpose</strong> expresses purpose with the <strong>relative pronoun</strong> (quī, quae, quod) plus the <strong>subjunctive</strong> instead of ut. <em>Mīsit virōs quī adjuvārent</em> = 'he sent men who would help' — men 'to help.' The relative still agrees with its antecedent in gender and number; the subjunctive marks the purpose.",referenceTable:{title:"Relative Clause of Purpose",headers:["Construction","Meaning"],rows:[["Mīsit virōs quī adjuvārent","He sent men to help (who would help)"],["Nūntium mīsit quī auxilium peteret","He sent a messenger to seek aid"],["Virī quī pugnant (indicative)","The men who fight (plain description)"]],highlightRows:[0]},vocabularyTable:vt("Lesson 80 Vocabulary",[w("dēdūcō, dēdūcere","lead down, lead away","day-DOO-koh"),w("cognōscō, cognōscere","learn, recognize","kog-NOH-skoh"),w("nūntius","messenger, message","NOON-tsee-oos","m.","2nd decl."),w("nātūra","nature","nah-TOO-rah","f.","1st decl."),w("-que","and (enclitic)","kweh"),w("injūria","injustice, injury","een-YOO-ree-ah","f.","1st decl.")]),vocabulary:[w("dēdūcō, dēdūcere","lead down, lead away","day-DOO-koh"),w("cognōscō, cognōscere","learn, recognize","kog-NOH-skoh"),w("nūntius","messenger, message","NOON-tsee-oos","m.","2nd decl."),w("nātūra","nature","nah-TOO-rah","f.","1st decl."),w("-que","and (enclitic)","kweh"),w("injūria","injustice, injury","een-YOO-ree-ah","f.","1st decl.")],teachingSteps:[{title:"Purpose Without ut",explanation:"Purpose can be expressed by the relative pronoun + subjunctive instead of ut + subjunctive. Mīsit virōs quī adjuvārent = he sent men who would help — i.e., men to help.",exampleLatin:"Mīsit virōs quī adjuvārent.",exampleEnglish:"He sent men to help (who would help).",tip:"The subjunctive adjuvārent is the signal that this is purpose, not plain description."},{title:"The Relative Still Agrees",explanation:"The relative pronoun keeps its ordinary job: it agrees with its antecedent in gender and number, and its case comes from its own clause. In virōs quī adjuvārent, quī is masculine plural because virōs is masculine plural.",exampleLatin:"Nūntium mīsit quī auxilium peteret.",exampleEnglish:"He sent a messenger to seek aid.",tip:"peteret = might seek — imperfect subjunctive of petō, secondary sequence after mīsit."},{title:"Spotting the Difference",explanation:"An ordinary relative clause uses the indicative: virī quī pugnant (the men who fight). Change the mood to the subjunctive and the same structure becomes purpose: mīsit virōs quī pugnent (he sent men to fight).",exampleLatin:"Virī quī pugnant / Mīsit virōs quī pugnent.",exampleEnglish:"the men who fight / he sent men to fight",tip:"Indicative = description; subjunctive = purpose."}],comprehensionCheck:[{question:"A relative clause of purpose is introduced by…",options:["a relative pronoun + subjunctive","ut + indicative","quod + indicative","nē + infinitive"],correctIndex:0,explanation:"quī, quae, quod + subjunctive expresses purpose."},{question:"Mīsit virōs quī adjuvārent means…",options:["he sent men to help","he sent the men who helped","the men sent him","he helps the men"],correctIndex:0,explanation:"quī adjuvārent (subjunctive) = who would help, i.e., to help."},{question:"cognōscō means…",options:["I learn, recognize","I send","I lead down","I announce"],correctIndex:0,explanation:"cognōscō, cognōscere = I learn, recognize."}],exercises:[mc("l80-q1","Mīsit virōs quī adjuvārent means…",["he sent men to help","he sent the men who were helping","the men helped him","he helped the men"],0),mc("l80-q2","The verb of a relative clause of purpose is in the…",["subjunctive","indicative","imperative","infinitive"],0),fill("l80-q3","dēdūcō means: I ___","lead down",["lead away","lead down, lead away"]),mc("l80-q4","Which is purpose, not plain description?",["Mīsit virōs quī adjuvārent","Virī quī pugnant sunt fortēs","Mīlitēs quōs vīdī sunt fortēs","Nūntius quī venit"],0),mc("l80-q5","nūntius means…",["messenger, message","envoy","guard","tribune"],0),fill("l80-q6","-que means ___","and",["and (enclitic)"]),mc("l80-q7","injūria means…",["injustice, injury","memory","friendship","nature"],0),match("l80-q8","Match word and meaning",[mp("cognōscō","I learn, recognize"),mp("nūntius","messenger"),mp("nātūra","nature"),mp("dēdūcō","I lead down")])]},
{id:81,title:"Purpose Clauses with quō",subtitle:"quō + comparative + subjunctive",concept:"When a purpose clause contains a <strong>comparative</strong> — an adverb like <em>facilius</em> ('more easily') or <em>diūtius</em> ('longer') — Latin introduces it with <strong>quō</strong> rather than ut: <strong>quō + comparative + subjunctive</strong>. <em>Venit quō facilius videat</em> = 'he comes so that he may see more easily.'",referenceTable:{title:"quō + Comparative + Subjunctive",headers:["Purpose clause","Meaning"],rows:[["quō facilius videat","so that he may see more easily"],["quō diūtius pugnent","so that they may fight longer"],["quō celerius perveniant","so that they may arrive more quickly"],["quō facilius expugnent","so that they may storm it more easily"]],highlightRows:[0]},vocabularyTable:vt("Lesson 81 Vocabulary",[w("diūtius","longer","dee-OO-tsee-oos"),w("facilius","more easily","fah-KEE-lee-oos"),w("appropinquō, appropinquāre","approach (+ dat.)","ap-proh-PEEN-kwoh"),w("vāstō, vāstāre","lay waste, devastate","VAH-stoh"),w("custōs, custōdis","guard","KOOS-tohs, koos-TOH-dees","m./f.","3rd decl.")]),vocabulary:[w("diūtius","longer","dee-OO-tsee-oos"),w("facilius","more easily","fah-KEE-lee-oos"),w("appropinquō, appropinquāre","approach (+ dat.)","ap-proh-PEEN-kwoh"),w("vāstō, vāstāre","lay waste, devastate","VAH-stoh"),w("custōs, custōdis","guard","KOOS-tohs, koos-TOH-dees","m./f.","3rd decl.")],teachingSteps:[{title:"Why quō?",explanation:"A purpose clause that contains a comparative — an adverb like facilius (more easily) or diūtius (longer) — is introduced by quō instead of ut. The pattern is quō + comparative + subjunctive.",exampleLatin:"Venit quō facilius videat.",exampleEnglish:"He comes so that he may see more easily.",tip:"Think of quō as 'so that, by which the more'."},{title:"The Comparative Adverbs",explanation:"celeriter → celerius (more quickly); facile → facilius (more easily); diū → diūtius (longer). These -ius forms are the comparative adverbs you will meet inside quō-clauses.",exampleLatin:"facilius, diūtius, celerius",exampleEnglish:"more easily, longer, more quickly",tip:"The -ius ending marks the comparative adverb."},{title:"Putting It Together",explanation:"Mīlitēs appropinquant quō facilius oppugnent — the soldiers approach so that they may attack more easily. The subjunctive remains the mark of purpose; quō signals the comparative.",exampleLatin:"Mīlitēs appropinquant quō facilius oppugnent.",exampleEnglish:"The soldiers approach so that they may attack more easily.",tip:"appropinquō takes the dative: appropinquant oppidō = they approach the town."}],comprehensionCheck:[{question:"Purpose clauses containing a comparative are introduced by…",options:["quō","ut","quod","nē"],correctIndex:0,explanation:"quō + comparative + subjunctive expresses purpose with a comparative."},{question:"facilius means…",options:["more easily","easily","easier","most easily"],correctIndex:0,explanation:"facilius is the comparative adverb: more easily."},{question:"appropinquō takes the…",options:["dative","accusative","ablative","genitive"],correctIndex:0,explanation:"appropinquō, 'to approach', governs the dative: oppidō appropinquant."}],exercises:[mc("l81-q1","A purpose clause with a comparative is introduced by…",["quō","ut","quod","nē"],0),mc("l81-q2","diūtius means…",["longer","for a long time","daily","more often"],0),fill("l81-q3","facilius means ___","more easily"),mc("l81-q4","vāstō means…",["I lay waste, devastate","I guard","I approach","I storm"],0),fill("l81-q5","Translate: Venit quō facilius videat","he comes so that he may see more easily",["he comes to see more easily"]),mc("l81-q6","custōs means…",["guard","hostage","envoy","messenger"],0),mc("l81-q7","appropinquō takes the…",["dative","accusative","ablative","genitive"],0),match("l81-q8","Match word and meaning",[mp("diūtius","longer"),mp("facilius","more easily"),mp("appropinquō","I approach"),mp("vāstō","I lay waste")])]}
